INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.82.0',
  '2026-09-03',
  'Checker: отметка «в работе» и многострочное поле пункта',
  E'У пункта появилась необязательная отметка «🚧 В работе» — включается в окне пункта (✏️ или долгое нажатие). Такой пункт видно в списке: вместо галочки половина закрашенного квадрата, название акцентным цветом. В полоске прогресса группы «в работе» показывается приглушённым сегментом — группа, где всё начато и ничего не закончено, больше не выглядит нетронутой.\n\nОтметка снимается сама, когда пункт становится сделанным: и по галочке, и по массовому «отметить все», и при повторяющемся сбросе группы. Сделанное в работе не бывает.\n\nНазвание пункта теперь правится в поле, которое растёт под текст: пункты бывают на две-три строки, а в однострочном поле правился только видимый кусок. Enter ставит перенос строки, сохранение — кнопкой или Ctrl+Enter.',
  E'checker_items.in_progress BOOLEAN (миграция 0113). Отдельный флаг, а не третье значение done: по done считаются прогресс группы, история и повторяющиеся сбросы — делать его тройственным значило бы переписать всё это.\n\nСовместимость «done + in_progress» держит сама БД: в UpdateCheckItem стоит CASE WHEN COALESCE($3, done) THEN false ELSE COALESCE($7, in_progress) END, поэтому галочка снимает флаг, даже если клиент прислал оба поля в одном запросе. То же в BulkSetItemsDone (check_all) и в snapshotAndReset. На клиенте флаг гасится сразу, до ответа сервера, иначе галочка и «в работе» на миг горят вместе.\n\nГрабля при правке: в updateItem условие вызова UpdateCheckItem перечисляет поля запроса — новое поле надо добавлять и туда, иначе патч только с in_progress молча ничего не делает (поймано на тесте).\n\nПоле названия переведено на textarea с автовысотой; общий хелпер shared/autoGrow.ts (сброс height в auto перед замером — иначе scrollHeight не уменьшается, и поле не сжимается обратно; потолок 320px, чтобы длинный текст не выталкивал кнопки модалки за экран). Тем же хелпером теперь живут поле нового пункта и заметка.\n\nВид «в работе» — половина квадрата, залитая через linear-gradient с жёсткой границей, а не полупрозрачная заливка: на 20 пикселях приглушённая заливка читалась почти как сплошная и путалась с «сделано». Форма, а не только цвет — состояние читается и в темах с приглушённым акцентом.'
);
-- +goose StatementEnd

